def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_last = history[-1][1]
    me_last = history[-1][0]
    if n == 1:
        return 'D' if opp_last == 'D' else 'C'
    if n == 99:
        return 'D'
    opp_defects = 0
    my_defects = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_defects += 1
        if history[i][0] == 'D':
            my_defects += 1
    ratio = opp_defects / n
    if ratio > 0.4:
        if rng.random() < 0.85:
            return 'D'
        return 'C'
    if ratio > 0.15:
        if opp_last == 'D':
            if history[-2][1] == 'D':
                return 'D'
            return 'D' if rng.random() < 0.5 else 'C'
        return 'C'
    if opp_last == 'D':
        return 'D'
    if n >= 3 and history[-1][1] == 'D' and history[-2][1] == 'D':
        return 'D'
    if n >= 2 and history[-1][1] == 'C' and history[-2][1] == 'C':
        return 'C'
    if n > 50 and opp_defects == 0:
        if rng.random() < 0.1:
            return 'D'
        return 'C'
    return 'C'

